examples.template:
@OptIn(ExperimentalMonarchApi::class)
MonarchAiConversationHeader(
    title = title,
    agent = MonarchAiAgentRef(name = {{agent}}),
    onRename = { next -> title = next },
    model = { Text({{model}}, style = MonarchTheme.typography.caption) },
) {
    MonarchButton(
        text = {{share.label}},
        onClick = {},
        variant = MonarchButtonVariant.{{share.variant|pascal}},
        size = MonarchButtonSize.{{share.size|pascal}},
    )
    Box {
        MonarchButton(
            text = {{more.label}},
            onClick = { menuOpen = true },
            variant = MonarchButtonVariant.{{more.variant|pascal}},
            size = MonarchButtonSize.{{more.size|pascal}},
        )
        MonarchMenu(expanded = menuOpen, onDismissRequest = { menuOpen = false }) {
            MonarchMenuItem(text = {{more.items.0.label}}, onClick = { menuOpen = false })
            MonarchMenuItem(text = {{more.items.1.label}}, onClick = { menuOpen = false }, destructive = true)
        }
    }
}

