@OptIn(ExperimentalMonarchApi::class)
MonarchAiConversationHeader(
    title = title,
    agent = MonarchAiAgentRef(name = "Assistant"),
    onRename = { next -> title = next },
    model = { Text("Balanced model", style = MonarchTheme.typography.caption) },
) {
    MonarchButton(
        text = "Share",
        onClick = {},
        variant = MonarchButtonVariant.Secondary,
        size = MonarchButtonSize.Sm,
    )
    Box {
        MonarchButton(
            text = "More",
            onClick = { menuOpen = true },
            variant = MonarchButtonVariant.Ghost,
            size = MonarchButtonSize.Sm,
        )
        MonarchMenu(expanded = menuOpen, onDismissRequest = { menuOpen = false }) {
            MonarchMenuItem(text = "Export", onClick = { menuOpen = false })
            MonarchMenuItem(text = "Delete conversation", onClick = { menuOpen = false }, destructive = true)
        }
    }
}
